	"kind" text NOT NULL,
	"correct" boolean NOT NULL,
	"xp" integer NOT NULL,
	"session_key" text NOT NULL,
	"step_index" integer NOT NULL,
	"attempt_no" integer NOT NULL,
	"idempotency_key" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "vocab_activity_idempotency_key_unique" UNIQUE("idempotency_key"),
	CONSTRAINT "vocab_activity_kind_check" CHECK ("vocab_activity"."kind" in ('learn-complete', 'session-step'))
);
